<template><view class="page"><view class="page-head"><text class="eyebrow">PROFILE</text><view class="page-title">修改资料</view><text class="muted">设置一个方便大家识别的昵称。</text></view><view class="card form-card"><view class="field"><text class="field-label">昵称</text><input v-model="nickname" class="input" maxlength="30" placeholder="请输入昵称" /></view><button class="primary-btn" @click="save">保存修改</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{api}from'@/services/api';import{currentUser}from'@/services/session';const nickname=ref('');onLoad(()=>nickname.value=currentUser()?.nickname||'');async function save(){if(!nickname.value.trim())return uni.showToast({title:'昵称不能为空',icon:'none'});await api('/users/me','PATCH',{nickname:nickname.value});uni.showToast({title:'已保存'});setTimeout(()=>uni.navigateBack(),500)}</script>
